#!/usr/bin/env python3
"""Turn the console UI into a C array so the payload serves it without any files.

    python3 tools/embed.py ui/index.html build/ui_data.cpp kIndexHtml
"""

import sys

def main() -> int:
    if len(sys.argv) != 4:
        print(__doc__, file=sys.stderr)
        return 2

    source, output, symbol = sys.argv[1], sys.argv[2], sys.argv[3]
    with open(source, "rb") as handle:
        data = handle.read()

    lines = [
        "// generated by tools/embed.py — do not edit",
        "#include <cstddef>",
        "",
        f'extern const unsigned char {symbol}[] = {{',
    ]

    row = []
    for index, byte in enumerate(data):
        row.append(f"0x{byte:02x},")
        if len(row) == 16:
            lines.append("  " + " ".join(row))
            row = []
    if row:
        lines.append("  " + " ".join(row))

    lines.append("};")
    lines.append(f"extern const unsigned int {symbol}Len = {len(data)};")
    lines.append("")

    with open(output, "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines))

    print(f"embed: {source} -> {output} ({len(data)} bytes as {symbol})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
